const optionRows = $("Get options").all().map((i) => i.json).filter((r) => r.poll_id);
const voteRows = $("Get votes").all().map((i) => i.json).filter((r) => r.poll_id);

// One row per person per poll is intended, but the upsert is not
// atomic, so keep only the newest row per (poll_id, user_sub).
const latest = new Map();
for (const row of voteRows) {
  const key = `${row.poll_id}::${row.user_sub}`;
  const seen = latest.get(key);
  if (!seen || new Date(row.updatedAt) > new Date(seen.updatedAt)) latest.set(key, row);
}

const byPoll = new Map();
const poll = (id) => {
  if (!byPoll.has(id)) byPoll.set(id, { pollId: id, options: new Map(), voters: 0 });
  return byPoll.get(id);
};
for (const row of optionRows) {
  poll(row.poll_id).options.set(row.value, {
    value: row.value,
    count: 0,
    suggested: row.created_by_sub !== "seed",
  });
}
for (const row of latest.values()) {
  let selected;
  try {
    selected = JSON.parse(row.options);
  } catch {
    selected = [];
  }
  if (!Array.isArray(selected) || selected.length === 0) continue;
  const p = poll(row.poll_id);
  p.voters += 1;
  for (const value of selected) {
    const option = p.options.get(value);
    // Values no longer on the option list are ignored.
    if (option) option.count += 1;
  }
}

return [
  {
    json: {
      polls: [...byPoll.values()].map((p) => ({
        pollId: p.pollId,
        voters: p.voters,
        options: [...p.options.values()],
      })),
    },
  },
];
